(2501095, 343252, 23478, '<td valign="top">Nice contrasting colors, also the DOF is good as is the inclusion of the corner of the room to fit the context of the challenge...8.</td>', 'Nice contrasting colors, also the DOF is good as is the inclusion of the corner of the room to fit the context of the challenge...8.', '2006-06-09 05:38:00.000000', NULL, 1),
(2501101, 343253, 23478, '<td valign="top">I like it... the angle and set up here are very appealing, as is the lighting &amp; the shadows... Well done.</td>', 'I like it... the angle and set up here are very appealing, as is the lighting & the shadows... Well done.', '2006-06-09 05:40:58.000000', NULL, 1),
