(2501364, 343231, 27133, '<td valign="top">Beautiful colours and clarity.  Great image.</td>', 'Beautiful colours and clarity.  Great image.', '2006-06-09 08:19:50.000000', NULL, 1),
(2501365, 343074, 27133, '<td valign="top">Very sad.</td>', 'Very sad.', '2006-06-09 08:20:05.000000', NULL, 1),
