(2503139, 342312, 54731, '<td valign="top">This is just great! What kind of room is this? Looks like an optical illusion! <br/>EDIT: Now that I voted on all, you are the only 10. You should win ;)</td>', 'This is just great! What kind of room is this? Looks like an optical illusion! EDIT: Now that I voted on all, you are the only 10. You should win ;)', '2006-06-09 20:40:52.000000', NULL, 1),
(2503195, 342798, 24642, '<td valign="top">A very clever idea nicely executed.</td>', 'A very clever idea nicely executed.', '2006-06-09 20:59:46.000000', NULL, 1),
(2503196, 340507, 24642, '<td valign="top">A good sens of space and drama.</td>', 'A good sens of space and drama.', '2006-06-09 21:00:09.000000', NULL, 1),
(2503197, 343212, 24642, '<td valign="top">A nice shot with a brilliant title.</td>', 'A nice shot with a brilliant title.', '2006-06-09 21:00:54.000000', NULL, 1),
(2503326, 342700, 29451, '<td valign="top">Superb!  The best of the left behind teddy bear shots - and my favorite in the challenge.  I could do without some of the debris in the front right corner, but the rest is perfect.  The bear has some human qualities the way you''ve photographed him. :) Well done.</td>', 'Superb!  The best of the left behind teddy bear shots - and my favorite in the challenge.  I could do without some of the debris in the front right corner, but the rest is perfect.  The bear has some human qualities the way you''ve photographed him. :) Well done.', '2006-06-09 21:47:58.000000', NULL, 1),
(2503328, 343255, 29451, '<td valign="top">Great concept, well done.  One of the more creative entries.</td>', 'Great concept, well done.  One of the more creative entries.', '2006-06-09 21:48:58.000000', NULL, 1),
(2503329, 342608, 29451, '<td valign="top">Wonderfully dark, great lighting - I like it.</td>', 'Wonderfully dark, great lighting - I like it.', '2006-06-09 21:50:01.000000', NULL, 1),
