(2503335, 342312, 29451, '<td valign="top">Very intriguing - I like the monochromatic tones and the perspective.</td>', 'Very intriguing - I like the monochromatic tones and the perspective.', '2006-06-09 21:52:47.000000', NULL, 1),
(2503341, 342213, 29451, '<td valign="top">What a lovely model.  Nice composition, I might like to see more of the room, though.</td>', 'What a lovely model.  Nice composition, I might like to see more of the room, though.', '2006-06-09 21:54:56.000000', NULL, 1),
