(2504792, 343239, 20530, '<td valign="top">Very unexpected! Nice use of selective desat. I like the diagonal created by the subject. Interesting with lots of energy.</td>', 'Very unexpected! Nice use of selective desat. I like the diagonal created by the subject. Interesting with lots of energy.', '2006-06-10 14:09:36.000000', NULL, 1),
(2504819, 342051, 20530, '<td valign="top">Nice, long lighting. Interesting subject matter. I like the colors and composition.</td>', 'Nice, long lighting. Interesting subject matter. I like the colors and composition.', '2006-06-10 14:25:13.000000', NULL, 1),
(2504840, 343249, 59891, '<td valign="top">Though the subject is really gruesome, I must say that the photo is very well done.  Excellent lighting and composition.  Good balance between the thing and the space, and the title adds a story for the full package.</td>', 'Though the subject is really gruesome, I must say that the photo is very well done.  Excellent lighting and composition.  Good balance between the thing and the space, and the title adds a story for the full package.', '2006-06-10 14:55:20.000000', NULL, 1),
(2504845, 340816, 59891, '<td valign="top">The careful placement of the doll doesn''t make the story ring true to me, but it certainly makes for good lighting and composition.</td>', 'The careful placement of the doll doesn''t make the story ring true to me, but it certainly makes for good lighting and composition.', '2006-06-10 14:59:06.000000', NULL, 1),
(2504846, 342700, 59891, '<td valign="top">While I might quibble about how empty the room is with all that detritus, I still enjoy the photo and the story it tells.  Composition and lighting are both nicely done.</td>', 'While I might quibble about how empty the room is with all that detritus, I still enjoy the photo and the story it tells.  Composition and lighting are both nicely done.', '2006-06-10 15:01:37.000000', NULL, 1),
(2504858, 340507, 30982, '<td valign="top">Definitely an empty room, but overall a bit flat.  I do like the light along the walls, but needs a bit more of it.</td>', 'Definitely an empty room, but overall a bit flat.  I do like the light along the walls, but needs a bit more of it.', '2006-06-10 15:15:29.000000', NULL, 1),
(2504859, 340273, 30982, '<td valign="top">I like the "room" itself and the angle of the shot.  Not sure I like the placement of the human as much.</td>', 'I like the "room" itself and the angle of the shot.  Not sure I like the placement of the human as much.', '2006-06-10 15:17:00.000000', NULL, 1),
